namespace Notifications;

/// <summary>Computes the backoff delay before the next delivery attempt.</summary>
public sealed class RetryPolicy
{
    private const int MaximumAttempt = 10;
    private const int MaximumDelay = 3600;
    private const int BusyThreshold = 600;

    public int NextDelay(int attempt, Channel channel, bool serverBusy)
    {
        if (attempt <= 0)
            return 0;

        if (attempt > MaximumAttempt)
            return MaximumDelay;

        var delay = GetBaseDelay(channel) * attempt;
        return AdjustDelay(delay, attempt, serverBusy);
    }

    private static int GetBaseDelay(Channel channel) => channel switch
    {
        Channel.Email => 30,
        Channel.Sms => 10,
        Channel.Push => 5,
        _ => 15
    };

    private static int AdjustDelay(int delay, int attempt, bool serverBusy)
    {
        if (serverBusy && delay < BusyThreshold)
            delay *= 2;

        if (delay > MaximumDelay)
            return MaximumDelay;

        if (delay < 1)
            return 1;

        return attempt > 7 ? delay + 100 : delay;
    }
}
